-- The Noble Exchange (NeX) store catalogue, and the Aurum journal entry types the client is missing.
-- generated by a one-off script from invTypes category 30 (Apparel);  see doc/code_and_design_notes/planning/PLAN-nex-store-aur.md
--
-- Why:  storeServer.GetAvailableOffers (src/eve-server/store/StoreService.cpp) sells what storeOffers holds:  one offer
--  per row, 'quantity' units of typeID for priceAUR Aurum a bundle, while enabled = 1.  Seeded with every published
--  apparel type (209) and the three unpublished hair styles, offerID = typeID.  The six black monocle resources
--  (paperdollResources typeID -1) and resource 1072 (typeID 4055, in no invTypes) have no type to sell.
--  Prices (AUR), from PC Gamer June 2011 ("most clothes 3,200-4,400 AUR", the monocle 12,000 AUR) and CCP's
--  "NeX Retail Pricing Strategy":
--   casual tops ('Quafe' T-shirts, 'Street', 'Form', 'Function', 'Avenue')  3,200
--   dress tops ('Sterling' shirts and blouses)                            3,600
--   bottoms (pants and skirts)                                            3,400
--   footwear (boots and heels)                                            3,600
--   outerwear (coats and 'Structure' dresses)                             4,400
--   + 400 for a premium finish (gold, leather, satin, platinum, silver, special edition in the name)
--   eyewear:  GDN-9 goggles 8,000, Odin Synthetic Eye 10,000, Looking Glass Monocle 12,000
--   hair styles 2,000
--  Change prices or switch offers off here;  the client reloads offers when it reopens the store.
--
--  jnlEntryTypeIDs:  the wallet drops journal rows whose type GetEntryTypes doesn't list (wallet.py).  109
--  refAurumGiveAway (GM grants, the stipend) and 111 refAurumTokenConversion (appConst) were missing;  110 isn't a
--  client type.  entryTypeNameID is the client's localization message:  109 follows the table's sequence (106-108 =
--  59898-59900);  111's message isn't known and shares 109's.
--
-- Idempotent:  CREATE TABLE IF NOT EXISTS, INSERT IGNORE.

-- +migrate Up
CREATE TABLE IF NOT EXISTS `storeOffers` (
  `offerID` int(10) unsigned NOT NULL,
  `typeID` int(10) unsigned NOT NULL,
  `quantity` int(10) unsigned NOT NULL DEFAULT 1,
  `priceAUR` int(10) unsigned NOT NULL,
  `enabled` tinyint(1) unsigned NOT NULL DEFAULT 1,
  `label` varchar(100) NOT NULL DEFAULT '',
  PRIMARY KEY (`offerID`),
  KEY `typeID` (`typeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;



-- +migrate Down
DROP TABLE IF EXISTS `storeOffers`;
DELETE FROM `jnlEntryTypeIDs` WHERE `entryTypeID` IN (109, 111);
